2	
3	/**
4	 * Derives an owner's {@code identityKey}, a descriptive value exposed on the owner
5	 * response.
6	 *
7	 * <p>The key is {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
8	 * By the time an owner is built its telephone has been normalized to E.164 and its email
9	 * lower-cased, so those stored values are the normalized forms. A null email or a null
10	 * {@code householdId} contributes an empty segment.
11	 *
12	 * <p>Duplicate detection itself is now keyed on the {@code householdId} alone (see the
13	 * create pipeline's household duplicate block), not on this whole key.
14	 */
15	public final class IdentityKey {
16	
17	    private IdentityKey() {
18	    }
19	
20	    /** The identity key for the given owner. */
21	    public static String of(Owner owner) {
22	        return segment(owner.getTelephone()) + "|" + segment(owner.getEmail()) + "|"
23	                + segment(owner.getHouseholdId());
24	    }
25	
26	    private static String segment(String value) {
27	        return value == null ? "" : value;
28	    }
29	}
