27	        }
28	        String householdId = owner.getHouseholdId();
29	        for (Owner existing : ownerRepository.findAll()) {
30	            if (existing.isDeleted()) {
31	                continue; // a soft-deleted owner no longer blocks a duplicate
32	            }
33	            if (householdId.equals(existing.getHouseholdId())) {
34	                throw new OwnerIdentityConflictException(householdId);
35	            }
36	        }
