4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.model.Sha256;
6	
7	/**
8	 * Assigns the owner's {@code householdId} deterministically: the first 12 hexadecimal
9	 * characters of the SHA-256 digest over {@code normalizedLastName + '|' + postcode}. Two
10	 * owners with the same last name and postcode therefore always derive the <em>same</em>
11	 * {@code householdId} — they are automatically the same household, with no opt-in and no
12	 * back-fill. Runs after {@link BuildOwner} (so the entity carries its stored last name and
13	 * postcode) and before {@link CheckOwnerIdentityUnique} (so the household id is available
14	 * to the duplicate block) and {@link AssignHouseholdSize}.
15	 *
16	 * <p>The request flag {@code sharesHousehold} no longer creates the link; it only lets a
17	 * second owner in an existing household bypass the duplicate block (see
18	 * {@link CheckOwnerIdentityUnique}).
19	 */
20	public class AssignHousehold {
21	
22	    public void service(@Val Owner owner) {
23	        String key = normalize(owner.getLastName()) + "|" + nullToEmpty(owner.getPostcode());
24	        owner.setHouseholdId(hash12(key));
25	    }
26	
27	    /** The first 12 lower-case hex characters of SHA-256 over the UTF-8 bytes of {@code value}. */
28	    private static String hash12(String value) {
29	        return Sha256.hex(value).substring(0, 12);
30	    }
31	
32	    private static String nullToEmpty(String value) {
33	        return value == null ? "" : value;
34	    }
35	
36	    /** Lower-cased, trimmed, with internal whitespace runs collapsed to a single space. */
37	    private static String normalize(String value) {
38	        if (value == null) {
39	            return "";
40	        }
41	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
42	    }
43	}
