3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Flags a soft (non-hard) duplicate. Runs after {@link CheckOwnerIdentityUnique} — so a
10	 * household duplicate has already been rejected with 409 — and before {@link SaveOwner}, so
11	 * the flags are computed against the owners that existed before this create and are
12	 * persisted with the new owner.
13	 *
14	 * <p>A <em>declared</em> household member (a request that opted in via
15	 * {@code sharesHousehold}) is never a suspected duplicate: it is deliberately created into
16	 * an existing household, so it is left un-flagged.
17	 *
18	 * <p>Otherwise an owner is a possible duplicate when it shares an existing owner's
19	 * {@code lastName} (compared case-insensitively) and {@code postcode} while carrying a
20	 * <em>different</em> telephone. When such an existing owner is found,
21	 * {@code possibleDuplicate} is set true and {@code possibleDuplicateOf} to that owner's id
22	 * (the lowest id when several match); otherwise {@code possibleDuplicate} is false and
23	 * {@code possibleDuplicateOf} null. A null postcode never matches, so it is never a possible
24	 * duplicate.
25	 */
26	public class AssignPossibleDuplicate {
27	
28	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
29	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
30	            owner.setPossibleDuplicate(false);
31	            owner.setPossibleDuplicateOf(null);
32	            return; // a declared household member is not a suspected duplicate
33	        }
34	        String lastName = owner.getLastName();
35	        String postcode = owner.getPostcode();
36	        String telephone = owner.getTelephone();
37	
38	        Owner match = null;
39	        if (postcode != null) {
40	            for (Owner existing : ownerRepository.findAll()) {
41	                if (existing.isDeleted()) {
42	                    continue; // a soft-deleted owner is not a possible duplicate match
43	                }
44	                if (postcode.equals(existing.getPostcode())
45	                        && equalsIgnoreCase(lastName, existing.getLastName())
46	                        && !equals(telephone, existing.getTelephone())) {
47	                    if (match == null || existing.getId() < match.getId()) {
48	                        match = existing;
49	                    }
50	                }
51	            }
52	        }
53	
54	        if (match != null) {
55	            owner.setPossibleDuplicate(true);
56	            owner.setPossibleDuplicateOf(match.getId());
57	        }
58	        else {
59	            owner.setPossibleDuplicate(false);
60	            owner.setPossibleDuplicateOf(null);
61	        }
62	    }
63	
64	    private static boolean equalsIgnoreCase(String a, String b) {
65	        return a == null ? b == null : a.equalsIgnoreCase(b);
66	    }
67	
68	    private static boolean equals(String a, String b) {
69	        return a == null ? b == null : a.equals(b);
70	    }
