1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.util.ArrayList;
5	import java.util.List;
6	import java.util.Set;
7	import java.util.regex.Pattern;
8	
9	import net.officefloor.plugin.variable.Out;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.escalation.OwnerFieldsInvalidException;
12	import org.springframework.web.bind.annotation.RequestBody;
13	
14	/**
15	 * Rejects a create request that is missing or blank in any required owner field, before
16	 * {@link BuildOwner} runs. Reads the body once and republishes it for later steps.
17	 */
18	public class ValidateOwnerFields {
19	
20	    /** A syntactically valid address: local-part@domain with a dotted domain, no spaces. */
21	    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
22	
23	    /** Disposable email domains rejected outright: an email in one of these is a 400. */
24	    private static final Set<String> DISPOSABLE_DOMAINS =
25	            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
26	
27	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
28	            throws OwnerFieldsInvalidException {
29	        List<String> errors = new ArrayList<>();
30	        checkRequired("firstName", request.getFirstName(), errors);
31	        checkRequired("lastName", request.getLastName(), errors);
32	        checkRequired("city", request.getCity(), errors);
33	        checkRequired("telephone", request.getTelephone(), errors);
34	        normalizeAddress(request, errors);
35	        normalizeTelephone(request, errors);
36	        normalizeEmail(request, errors);
37	        validatePostcode(request, errors);
38	        validateRegistrationDate(request, errors);
39	        if (!errors.isEmpty()) {
40	            throw new OwnerFieldsInvalidException(errors);
41	        }
42	        validated.set(request);
43	    }
44	
45	    private static void checkRequired(String field, String value, List<String> errors) {
46	        if (value == null || value.isBlank()) {
47	            errors.add(field);
48	        }
49	    }
50	
51	    /**
52	     * Normalizes the supplied address, preferring the structured
53	     * {@code addressLine1}/{@code addressLine2} pair over the flat {@code address} (see
54	     * {@link AddressFields}), and stores the normalized parts and composed canonical
55	     * address back on the request so later steps persist, compare and return them. An
56	     * address is required in one form or the other: a request that supplies neither a
57	     * non-blank {@code addressLine1} nor a non-blank flat {@code address} is a 400 (adds an
58	     * "address" error) and nothing is stored back.
59	     */
60	    private static void normalizeAddress(OwnerFieldsDto request, List<String> errors) {
61	        if (!AddressFields.normalizeInto(request)) {
62	            errors.add("address");
63	        }
64	    }
65	
66	    /**
67	     * Normalizes the telephone to E.164 form (see {@link TelephoneE164}), storing the
68	     * result back on the request so later steps persist and return it. A value that
69	     * cannot form a valid E.164 number is a 400 (adds a "telephone" error).
70	     */
71	    private static void normalizeTelephone(OwnerFieldsDto request, List<String> errors) {
72	        String telephone = request.getTelephone();
73	        if (telephone == null) {
74	            return;
75	        }
76	        String e164 = TelephoneE164.toE164(telephone);
77	        if (e164 != null) {
78	            request.setTelephone(e164);
79	        }
80	        else if (!errors.contains("telephone")) {
81	            errors.add("telephone");
82	        }
83	    }
84	
85	    /**
86	     * Email is optional. When present (non-blank) it must be a syntactically valid address
87	     * whose domain is not on the disposable-domain blocklist; an invalid or disposable value
88	     * is a 400 (adds an "email" error). A valid value is stored lower-cased back on the request
89	     * so later steps persist and return it lower-cased.
90	     */
91	    private static void normalizeEmail(OwnerFieldsDto request, List<String> errors) {
92	        String email = request.getEmail();
93	        if (email == null || email.isBlank()) {
94	            return;
95	        }
96	        String trimmed = email.trim();
97	        if (EMAIL.matcher(trimmed).matches() && !isDisposableDomain(trimmed)) {
98	            request.setEmail(trimmed.toLowerCase());
99	        }
100	        else if (!errors.contains("email")) {
101	            errors.add("email");
102	        }
103	    }
104	
105	    /** True when the email's domain (case-insensitive) is on the disposable-domain blocklist. */
106	    private static boolean isDisposableDomain(String email) {
107	        int at = email.lastIndexOf('@');
108	        if (at < 0) {
109	            return false;
110	        }
111	        return DISPOSABLE_DOMAINS.contains(email.substring(at + 1).toLowerCase());
112	    }
113	
114	    /**
115	     * Postcode is optional. When present (non-blank) it must be a 4-digit value that is valid
116	     * for the owner's city per the fixed region ranges (see
117	     * {@link org.springframework.samples.petclinic.model.Postcode}); an out-of-range or
118	     * malformed value is a 400 (adds a "postcode" error). A valid value is stored trimmed back
119	     * on the request so later steps persist and return it. A city with no known region accepts
120	     * any 4-digit postcode, keeping the create request backward-compatible when absent.
121	     */
122	    /**
123	     * Registration date is optional (it defaults to the server's current date in
124	     * {@link BuildOwner} when absent). When supplied it must not be later than the server's
125	     * current date; a future value is a 400 (adds a "registrationDate" error).
126	     */
127	    private static void validateRegistrationDate(OwnerFieldsDto request, List<String> errors) {
128	        LocalDate registrationDate = request.getRegistrationDate();
129	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
130	            errors.add("registrationDate");
131	        }
132	    }
133	
134	    private static void validatePostcode(OwnerFieldsDto request, List<String> errors) {
135	        String postcode = request.getPostcode();
136	        if (postcode == null || postcode.isBlank()) {
137	            return;
138	        }
139	        String trimmed = postcode.trim();
140	        if (org.springframework.samples.petclinic.model.Postcode.isValidForCity(trimmed, request.getCity())) {
141	            request.setPostcode(trimmed);
142	        }
143	        else if (!errors.contains("postcode")) {
144	            errors.add("postcode");
145	        }
146	    }
147	}
