3	/**
4	 * Thrown when a create request would add a second owner to an existing household — i.e. an
5	 * owner whose deterministic {@code householdId} (derived from its last name and postcode)
6	 * equals that of an existing owner — without opting in via {@code sharesHousehold}. Handled
7	 * by {@link OwnerIdentityConflictExceptionHandler}, which responds 409 Conflict.
8	 */
9	public class OwnerIdentityConflictException extends Exception {
10	
11	    private final String householdId;
12	
13	    public OwnerIdentityConflictException(String householdId) {
14	        super("Another owner already exists in the same household: " + householdId);
15	        this.householdId = householdId;
16	    }
17	
18	    public String getHouseholdId() {
19	        return householdId;
20	    }
21	}
